define(["jquery","core/ajax","core/notification"],function(t,e,a){const l=t=>String(null==t?"":t).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");return{init:function(){const n=t('[data-region="ncl-submissions"]');n.length&&e.call([{methodname:"local_nexcodelab_get_submissions",args:{problemid:0,page:0,perpage:50}}])[0].then(t=>{const e=(t.submissions||[]).map(t=>"<tr><td>"+l(t.timestr)+'</td><td><a href="/local/nexcodelab/problem.php?id='+l(t.problemid)+'">'+l(t.problemname)+"</a></td><td>"+l(t.status)+"</td><td>"+l(t.passed)+"/"+l(t.total)+"</td><td>"+l(t.language)+"</td></tr>").join("");return n.find('[data-region="subs"]').html(e?'<table class="ncl-table"><thead><tr><th>When</th><th>Problem</th><th>Status</th><th>Tests</th><th>Lang</th></tr></thead><tbody>'+e+"</tbody></table>":'<p class="ncl-empty">No submissions yet.</p>'),null}).catch(a.exception)}}});